section.slide.active>p{font-size:.97rem!important;line-height:1.3!important}
section.slide.active>#save-status{flex:0 1 auto!important;align-self:center;margin:2px 0 2px 12px!important}
section.slide [data-route-panel]>p{font-size:.95rem!important;line-height:1.3!important}
