section.slide #activity-feedback{font-size:.95rem!important;line-height:1.3!important}
section.slide #activity-board[data-kind="sequence"] .sequence-list{margin:0 0 2px!important}
section.slide #activity-board[data-kind="sequence"]>button{min-height:32px!important;padding:4px 12px!important}
section.slide .vary-box .vary-how{margin:0 0 4px!important}
