section.slide .vary-box .vary-status{margin:3px 0 0!important}
section.slide.active>#activity-board{margin-bottom:0!important}
@media (max-width:1100px){
section.slide p.local-help{font-size:.88rem!important;line-height:1.25!important;padding:3px 8px!important}
section.slide .round-box>p,section.slide .round-box h3{font-size:.95rem!important;line-height:1.25!important}
section.slide .round-options button{padding:4px 8px!important;min-height:32px!important}
