/* RE E4 print block (Claude, 27 Sep 2026). Last style in head of every RE lesson page and Pupil_Resources page. Each print section fits one A4 page; cut cards print as cut-out cards. */
@media print{
.print-section{font-size:10pt!important;line-height:1.3!important}
.print-section h2{font-size:13pt!important;margin:2.5mm 0 1.5mm!important}
.print-section h3{font-size:10.5pt!important;margin:2mm 0 1mm!important}
.print-section p,.print-section li{margin:0 0 1.2mm!important}
.print-section ol,.print-section ul{margin:0 0 1.5mm!important;padding-left:6mm!important}
.print-section th,.print-section td{padding:1.2mm 2mm!important}
.print-section .book-cut-cards,.print-section .cut-card-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:3mm!important;margin:2mm 0 3mm!important}
.print-section .book-cut-card,.print-section .cut-card{border:1px dashed #334155!important;min-height:22mm!important;padding:3mm!important;box-sizing:border-box!important;display:flex!important;align-items:center!important;justify-content:center!important;text-align:center!important;font-size:11pt!important;font-weight:700!important;break-inside:avoid!important}
.print-section .evidence-list{display:grid!important;grid-template-columns:1fr 1fr!important;gap:3mm!important}
.print-section .evidence-card{margin:0!important;padding:2.5mm 3mm!important;break-inside:avoid!important}
.print-section .evidence-card p{margin:0 0 1mm!important}
}

